import {joinCases,createJoin,joinModel,changeJoin,joinExample} from './join-pieces-core.mjs';
import {joinCopy as copy,joinJobs,joinUnmatched,joinSource,joinOutput,joinEquation,joinReference} from './join-pieces-content.mjs';
import {commonRibbonArt} from './common-cuts-art.mjs';
import {hearButton} from './play-media.mjs';
import {createMissingView,startMissingCase,missingRibbonView,bindMissingRibbon} from './missing-ribbon-ui.mjs';
import {missingCopy} from './missing-ribbon-content.mjs';
import {wholeBundlesPage,bindWholeBundles,resetWholeBundles} from './whole-bundles-ui.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null,retireBinding=()=>{},stopBinding=()=>{};
export function resetJoinPieces(){retireBinding();stopBinding();stopBinding=()=>{};visit=null;resetWholeBundles();}
function current(state,id){if(!visit||visit.notebook!==state||visit.explorerId!==id){resetJoinPieces();visit={notebook:state,explorerId:id,caseId:null,cases:new Map(),reference:false,example:false,frame:0,panels:{},mode:'join',missing:createMissingView()};}return visit;}
const button=(action,label,disabled=false,extra='')=>`<button type="button" data-join-action="${action}" ${extra}${disabled?' disabled':''}>${esc(label)}</button>`;
const catalog=selected=>`<div class="join-catalog">${joinCases.map(c=>`<button type="button" data-join-start="${c.id}"${c.id===selected?' aria-current="true"':''}>${esc(joinJobs[c.id].title)} <span>A ${c.left.numerator}/${c.left.denominator} + B ${c.right.numerator}/${c.right.denominator}</span></button>`).join('')}</div>`;
function pattern(letter,id){return `<pattern id="${id}" width="10" height="10" patternUnits="userSpaceOnUse" class="join-pattern-${letter}">${letter==='A'?'<path d="M-2 2l4-4M0 10L10 0M8 12l4-4"/>':'<circle cx="3" cy="3" r="1.7"/><circle cx="8" cy="8" r="1.7"/>'}</pattern>`;}
// All material uses the parent's x=12, width=576, viewBox=600 whole.
function strip(denominator,slots,id,label){
 const width=576/denominator;
 const pieces=Array.from({length:denominator},(_,i)=>{
  const slot=slots[i],x=12+i*width;
  let shape='';
  if(slot){
   const neutral=slot.neutral===true;
   const kind=neutral?'join-neutral-piece':`join-shade-${slot.letter}${slot.moved?' join-moved':''}`;
   const source=neutral?'':` data-source="${slot.letter}"`;
   shape=`<rect class="${kind}" data-join-piece="${i}" data-slot="${i}"${source}${slot.moved?' data-moved="true"':''} x="${x}" y="22" width="${width}" height="36"/>`;
   if(!neutral&&!slot.moved)shape+=`<rect x="${x}" y="22" width="${width}" height="36" fill="url(#${id}-${slot.letter})"/><text class="join-piece-letter" x="${12+(i+.5)*width}" y="47" text-anchor="middle">${slot.letter}</text>`;
  }
  return shape+(i?`<path class="join-cut" d="M${x} 22v36"/>`:'');
 }).join('');
 return `<svg class="join-diagram" viewBox="0 0 600 78" role="img" aria-label="${esc(label)}" data-join-strip="${id.match(/output-(\d+)$/)?.[1]??''}"${id.includes('source-')?` data-join-tray="${id.endsWith('A')?'left':'right'}"`:''}><defs>${pattern('A',id+'-A')}${pattern('B',id+'-B')}</defs><rect class="join-whole" data-join-whole x="12" y="22" width="576" height="36"/>${pieces}<rect class="join-outline" x="12" y="22" width="576" height="36"/><path class="join-marker" d="M12 14v50M588 14v50"/><text x="12" y="75">0</text><text x="588" y="75" text-anchor="end">1</text></svg>`;
}
function originals(m,id){return `<section class="join-originals"><h3 data-join-read>Original lengths</h3>${['left','right'].map((s,i)=>`<div class="join-original" data-join-original="${s}"><p data-join-read><strong>${i?'B':'A'} original ${m[s].originalNumerator}/${m[s].originalDenominator}</strong> · Now ${m[s].numerator}/${m[s].denominator}</p>${commonRibbonArt(m[s],s,id)}</div>`).join('')}</section>`;}
function source(m,side,example){const row=m[side],letter=side==='left'?'A':'B',locked=m.count>0;return `<section class="join-source" data-join-source="${side}" data-remaining="${row.remaining}" data-moved="${row.moved}" data-denominator="${row.denominator}"><h3>Source tray ${letter}</h3>${strip(row.denominator,Array.from({length:row.numerator},(_,i)=>({letter,moved:i>=row.remaining})),`${example?'example':'live'}-source-${letter}`,joinSource(letter,row))}<p data-join-read>${joinSource(letter,row)}</p>${example?'':`<div class="join-actions">${button('split',`Split ${letter} pieces in 2`,locked||!row.canSplit2,`data-join-side="${side}" data-join-factor="2"`)}${button('split',`Split ${letter} pieces in 3`,locked||!row.canSplit3,`data-join-side="${side}" data-join-factor="3"`)}${button('uncut',`Undo ${letter} cut`,locked||!row.canUndo,`data-join-side="${side}"`)}${button('move',`Move one ${letter} piece`,!m.matched||row.remaining===0,`data-join-side="${side}"`)}</div>${m.matched&&row.remaining===0?`<p data-join-read>All ${letter} pieces have moved. Undo a move or return all the pieces to refill the trays.</p>`:''}`}</section>`;}
function output(m,example){return `<section class="join-output" data-join-output data-count="${m.count}" data-denominator="${m.denominator??''}"><h3>Joined so far</h3>${m.matched?Array.from({length:m.count>m.denominator?2:1},(_,whole)=>strip(m.denominator,m.sequence.slice(whole*m.denominator,(whole+1)*m.denominator).map(letter=>({letter})),`${example?'example':'live'}-output-${whole}`,`Joined whole strip ${whole+1}; ${m.sequence.slice(whole*m.denominator,(whole+1)*m.denominator).join(', ')||'no pieces yet'}.`)).join(''):''}<p data-join-read role="status">${joinOutput(m)}</p><p data-join-read>Pieces in move order: ${m.sequence.join(', ')||'none'}.</p>${!example&&m.complete?`<p class="join-complete" data-join-read>Both lengths are joined. ${joinEquation(m)}.</p>`:''}</section>`;}
function materials(m,example=false){return `${originals(m,example?'join-example':'join-live')}<div class="join-trays">${source(m,'left',example)}${source(m,'right',example)}</div>${output(m,example)}`;}
const panel=(v,key,title,text)=>`<details data-join-panel="${key}"${v.panels[key]?' open':''}><summary>${title}</summary><p data-join-read>${text}</p></details>`;
function example(v){const m=joinExample(v.frame);return `<div data-join-view="example" data-join-frame="${v.frame}"><h2 id="join-heading" tabindex="-1" data-join-read>Show me with quarters</h2><p data-join-read>These are separate example ribbons. Your ribbons stay as you left them.</p><p data-join-read>${copy.whole}</p>${materials(m,true)}${v.frame===4?`<section class="join-claim"><h3 data-join-read>Different claim: 2/6</h3>${strip(6,[{neutral:true},{neutral:true}],'join-false','Different claim: 2/6 of the same whole. This is shorter than A’s original half.')}</section>`:''}<p class="join-example-caption" data-join-read role="status">Picture ${v.frame+1} of 5. ${copy.frames[v.frame]}</p><nav class="join-actions" aria-label="Example pictures">${button('previous','Previous',v.frame===0)}${button('next','Next',v.frame===4)}${button('back','Back to my ribbons')}</nav>${hearButton('','Hear this picture')}</div>`;}
function board(v){const m=joinModel(v.cases.get(v.caseId)),job=joinJobs[v.caseId];if(!m||!job)return '';return `<div data-join-view="case" data-join-case="${v.caseId}"><h2 id="join-heading" tabindex="-1" data-join-read>${job.title}</h2><p class="join-request" data-join-read>${job.request}</p><p data-join-read>${copy.whole}</p><p class="join-stage" data-join-read>${m.complete?'Both lengths are joined. Undo a move or return the pieces to try another way.':m.matched?copy.matching:copy.cutting}</p>${materials(m)}${m.count||!m.matched?`<p data-join-read>${m.count?copy.locked:joinUnmatched(m)}</p>`:''}<p data-join-read>${copy.transfer}</p>${m.count===0?'<p class="join-cut-bound" data-join-read>Cuts can make at most 12 equal pieces in a whole. Undo a cut to try another way.</p>':''}<div class="join-actions join-reverse">${button('undo','Undo last move',m.count===0)}${button('return','Return all pieces',m.count===0)}</div><div class="join-actions">${button('reference','See the whole sum')}${button('example','Show me with quarters')}${hearButton('','Hear this table')}</div>${v.reference?`<p class="join-reference" id="join-reference" data-join-reference tabindex="-1" data-join-read>${joinReference(m)}</p>`:''}<details data-join-panel="chooser"${v.panels.chooser?' open':''}><summary>Choose another job</summary>${catalog(v.caseId)}</details>${panel(v,'talk','Talk together',copy.talk)}</div>`;}
export function joinPiecesPage(state,explorerId){
 const v=current(state,explorerId),work=v.mode==='missing'?v.missing:v;
 const body=v.mode==='bundles'?wholeBundlesPage(state,explorerId):v.mode==='missing'?missingRibbonView(work,strip):v.example?example(v):v.caseId?board(v):`<div data-join-view="chooser"><h2 id="join-heading" tabindex="-1" data-join-read>Choose two ribbons</h2><p data-join-read>${copy.introduction}</p><p data-join-read>${copy.whole}</p>${catalog(null)}</div>`;
 const modes=`<div class="join-modes" role="group" aria-label="Choose a ribbon question"><button type="button" data-join-mode="join" aria-pressed="${v.mode==='join'}">Join two lengths</button><button type="button" data-join-mode="missing" aria-pressed="${v.mode==='missing'}">Find the other length</button><button type="button" data-join-mode="bundles" aria-pressed="${v.mode==='bundles'}">Wholes and pieces</button></div>`;
 return `<section class="join-page" data-join-root data-join-selected-mode="${v.mode}"><header class="join-header"><nav aria-label="Nearby tables"><a href="#workshop/common-cuts">Common Cuts</a><a href="#cafe/portions">Join the Portions</a></nav><h1>${copy.title}</h1>${modes}</header><div class="join-worktop">${body}${v.mode==='bundles'?'':`<p class="join-visit" data-join-read>${copy.visit}</p>${panel(work,'grownup','For grown-ups',v.mode==='missing'?missingCopy.grownUp:copy.grownUp)}`}</div></section>`;
}
function bindingGuard(root,valid,stop){
 const controls=[root,...root.querySelectorAll('button,input,select,a,summary,details')].filter(n=>!n.closest?.('.speech-controls,drawn-howto')),chains=new Map(),retired=new WeakSet();let disconnected=false;
 const chain=n=>{const out=[];for(;n;n=n.parentNode)out.push(n);return out;};for(const n of controls)chains.set(n,chain(n));
 const audit=records=>{for(const r of records){if(r.type==='attributes'){for(const n of controls)if(chains.get(n).includes(r.target))retired.add(n);}else for(const removed of r.removedNodes)for(const n of controls)if(chains.get(n).includes(removed)||removed.contains?.(n))retired.add(n);}};
 const disconnect=()=>{if(!disconnected){disconnected=true;observer.disconnect();}};
 const observer=new MutationObserver(records=>{audit(records);if(!root.isConnected||!valid()||retired.has(root)){stop();disconnect();}});observer.observe(document,{childList:true,subtree:true,attributes:true,attributeFilter:['hidden','inert','aria-hidden','style','class']});
 return {disconnect,accepts(node){audit(observer.takeRecords());if(disconnected||!valid()||!root.isConnected||!root.contains(node)||node.disabled||retired.has(node))return false;const old=chains.get(node),now=chain(node);if(!old||old.length!==now.length||!old.every((n,i)=>n===now[i]))return false;for(let n=node;n?.nodeType===1;n=n.parentElement){const css=getComputedStyle(n);if(n.hidden||n.inert||n.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility))return false;if(n.tagName==='DETAILS'&&!n.open&&n!==node&&!n.querySelector(':scope>summary')?.contains(node))return false;}return node.getClientRects().length>0;}};
}
function visibleNarration(root){return [...root.querySelectorAll('[data-join-read]')].filter(node=>{for(let p=node;p&&p!==root;p=p.parentElement){const css=getComputedStyle(p);if(p.hidden||p.inert||p.getAttribute('aria-hidden')==='true'||css.display==='none'||['hidden','collapse'].includes(css.visibility)||p.tagName==='DETAILS'&&!p.open)return false;}return node.getClientRects().length>0;}).map(n=>n.textContent.replace(/\s+/g,' ').trim()).join(' ');}
export function bindJoinPieces(state,ctx){
 retireBinding();const root=document.querySelector('[data-join-root]');if(!root||!visit)return;
 const v=visit,mode=v.mode,work=mode==='missing'?v.missing:v,owner=typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId,caseId=work.caseId,material=work.cases.get(caseId),bytes=JSON.stringify(material),exampleOpen=work.example,frame=work.frame,referenceOpen=work.reference,parent=root.parentNode;
 const live=()=>root.isConnected&&root.parentNode===parent&&document.querySelector('[data-join-root]')===root&&location.hash==='#workshop/join-pieces'&&(typeof ctx.notebook==='function'?ctx.notebook():ctx.notebook??state)===state&&(!ctx.isActive||ctx.isActive())&&(typeof ctx.explorerId==='function'?ctx.explorerId():ctx.explorerId)===owner&&visit===v&&v.notebook===state&&v.explorerId===owner&&v.mode===mode&&(mode==='missing'?v.missing:v)===work&&work.caseId===caseId&&work.cases.get(caseId)===material&&JSON.stringify(material)===bytes&&work.example===exampleOpen&&work.frame===frame&&work.reference===referenceOpen;
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();},guard=bindingGuard(root,live,stop);retireBinding=guard.disconnect;stopBinding=stop;
 for(const control of root.querySelectorAll('button,input,select,a,summary,details')){if(control.closest('.speech-controls,drawn-howto'))continue;for(const type of ['click','input','change','keydown'])control.addEventListener(type,event=>{if(!guard.accepts(control)){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});}
 const redraw=(selector='#join-heading',fallback='[data-join-action="undo"]')=>{guard.disconnect();ctx.render();let target=document.querySelector(selector);if(!target||target.disabled||!target.getClientRects().length){selector=fallback;target=document.querySelector(selector);}if(!target||target.disabled||!target.getClientRects().length)selector='#join-heading';ctx.focus?.(selector);if(!ctx.focus)document.querySelector(selector)?.focus();};
 root.querySelectorAll('[data-join-panel]').forEach(panel=>panel.addEventListener('toggle',()=>{if(guard.accepts(panel)&&work.panels[panel.dataset.joinPanel]!==panel.open){work.panels[panel.dataset.joinPanel]=panel.open;stop();}}));
 root.querySelectorAll('[data-join-mode]').forEach(b=>b.addEventListener('click',()=>{
  const next=b.dataset.joinMode;if(!guard.accepts(b)||!['join','missing','bundles'].includes(next)||next===mode)return;
  stop();v.mode=next;
  if(next==='missing'&&!v.missing.caseId&&v.caseId)startMissingCase(v.missing,v.caseId);
  redraw(next==='bundles'?'#wb-heading':`[data-join-mode="${next}"]`);
 }));
 if(mode==='bundles'){bindWholeBundles(state,{...ctx,isActive:live});return;}
 // The existing speech resolver owns its first native click and global settings.
 root.addEventListener('click',event=>{const b=event.target.closest('[data-speak]');if(!b||!root.contains(b)||b.closest('.speech-controls,drawn-howto'))return;if(!guard.accepts(b)){event.preventDefault();event.stopImmediatePropagation();return;}b.dataset.speak=visibleNarration(root);},{capture:true});
 if(mode==='missing'){bindMissingRibbon(root,work,{accepts:control=>guard.accepts(control),redraw,stop});return;}
 root.querySelectorAll('[data-join-start]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b)||!joinJobs[b.dataset.joinStart])return;stop();v.caseId=b.dataset.joinStart;if(!v.cases.has(v.caseId))v.cases.set(v.caseId,createJoin(v.caseId));v.reference=false;v.example=false;v.panels.chooser=false;redraw();}));
 root.querySelectorAll('[data-join-action]').forEach(b=>b.addEventListener('click',()=>{if(!guard.accepts(b))return;const action=b.dataset.joinAction;
 if(action==='example'){stop();v.example=true;v.frame=0;redraw();return;}
 if(action==='back'&&exampleOpen){stop();v.example=false;v.frame=0;redraw('[data-join-action="example"]');return;}
 if(['previous','next'].includes(action)&&exampleOpen){const next=frame+(action==='next'?1:-1);if(!joinExample(next))return;stop();v.frame=next;redraw(`[data-join-action="${next===4?'previous':next===0?'next':action}"]`);return;}
 if(exampleOpen)return;
 if(action==='reference'){stop();v.reference=true;redraw('#join-reference');return;}
 const next=changeJoin(material,action,b.dataset.joinSide,Number(b.dataset.joinFactor));if(!next)return;stop();v.cases.set(caseId,next);v.reference=false;const selector=`[data-join-action="${action}"]${b.dataset.joinSide?`[data-join-side="${b.dataset.joinSide}"]`:''}${b.dataset.joinFactor?`[data-join-factor="${b.dataset.joinFactor}"]`:''}`;redraw(selector,action==='uncut'?`[data-join-action="split"][data-join-side="${b.dataset.joinSide}"]`:action==='split'?`[data-join-action="uncut"][data-join-side="${b.dataset.joinSide}"]`:'[data-join-action="move"][data-join-side="left"]');}));

}
